#!/usr/bin/env python3
"""Regenerate src/foods.rs from food-data/foods-26.3.json (pinned mcmeta 26.3)."""
from __future__ import annotations
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

def main() -> None:
    data = json.loads((ROOT / "food-data/foods-26.3.json").read_text())
    lines = [
        "// Generated by tools/generate_foods.py from food-data/foods-26.3.json. Do not edit by hand.",
        "// Source: misode/mcmeta 26.3-summary, item_components/data.json (Minecraft 26.3).",
        "",
        "use crate::preview::FoodInfo;",
        "",
        "pub const FOODS: &[(&str, FoodInfo)] = &[",
    ]
    for item, v in data["items"].items():
        tenths = round(v["saturation"] * 10)
        lines.append(
            f'    ("{item}", FoodInfo {{ nutrition: {v["nutrition"]}, '
            f'saturation_tenths: {tenths}, can_always_eat: {str(v["can_always_eat"]).lower()} }}),'
        )
    lines += [
        "];",
        "",
        "pub fn lookup(id: &str) -> Option<FoodInfo> {",
        "    FOODS",
        "        .binary_search_by_key(&id, |(name, _)| *name)",
        "        .ok()",
        "        .map(|i| FOODS[i].1)",
        "}",
        "",
    ]
    out = ROOT / "src/foods.rs"
    out.write_text("\n".join(lines))
    print(f" wrote {out} ({len(data['items'])} foods)")

if __name__ == "__main__":
    main()
